/// <reference path="./online-streaming-provider.d.ts" />

class Provider {
    baseUrl = "https://senshi.to"

    getSettings(): Settings {
        return {
            episodeServers: ["Server 1"],
            supportsDub: true,
        }
    }

    async search(query: SearchOptions): Promise<SearchResult[]> {
        const response = await fetch(`${this.baseUrl}/anime/filter`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify({
                searchTerm: query.query,
                page: 1,
                limit: 30,
            }),
        })

        const json = await response.json()
        const data = json?.data ?? json

        return data.map((item: any) => ({
            id: `${item.id}/${query.dub ? "dub" : "sub"}:${query.dub ? item.dub_count : item.sub_count}`,
            title: item.title_english || item.title || "",
            url: `${this.baseUrl}/watch/${item.public_id}/1`,
            subOrDub: query.dub ? "dub" : "sub",
        }))
    }

    async findEpisodes(Id: string): Promise<EpisodeDetails[]> {
        const [malId, epInfo] = Id.split("/");
        const [lang, totalCountStr] = epInfo.split(":");
        const totalEpisodes = parseInt(totalCountStr, 10) || 0;

        const episodes: EpisodeDetails[] = [];

        for (let i = 1; i <= totalEpisodes; i++) {
            episodes.push({
                id: `${malId}/${lang}`,
                number: i,
                url: `${this.baseUrl}/episode-embeds/${malId}/${i}`,
                title: `Episode ${i}`,
            });
        }

        return episodes;
    }

    async findEpisodeServer(episode: EpisodeDetails, _server: string): Promise<EpisodeServer> {
        const [id, lang] = episode.id.split("/")

        const response = await fetch(episode.url)

        const data: any[] = await response.json()

        const finalRes = await fetch(`https://s.vidcloud.se/_v1/sources?id=${data[0].remote_source_id}`, {
            headers: {
                "Referer": this.baseUrl + "/",
                "Origin": this.baseUrl
            }
        }).then(r => r.json())

        const subtitles = finalRes[0].tracks
            .filter((track: any) => track.label !== "chapter")
            .map((track: any, i: number) => ({
                id: `sub-${i}`,
                url: track.url,
                language: track.label,
                isDefault: false
            }))

        return {
            server: _server,
            headers: {
                "Referer": this.baseUrl + "/",
                "Origin": this.baseUrl
            },
            videoSources: [
                {
                    url: `https://senshi-proxy.vercel.app/api/master?id=${data[0].remote_source_id}&mode=${lang}&variant=0`,
                    quality: "1080p",
                    type: "m3u8",
                    subtitles,
                },
                {
                    url: `https://senshi-proxy.vercel.app/api/master?id=${data[0].remote_source_id}&mode=${lang}&variant=1`,
                    quality: "480p",
                    type: "m3u8",
                    subtitles,
                },
            ],
        }
    }
}
